use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn apply_run_search (details : & RunSearchDetails) -> Result < () > { eprintln ! ("  Running search command: '{}'" , details . command) ; let output = Command :: new ("sh") . arg ("-c") . arg (& details . command) . output () . with_context (| | format ! ("Failed to execute command: {}" , details . command)) ? ; let stdout = String :: from_utf8_lossy (& output . stdout) ; let stderr = String :: from_utf8_lossy (& output . stderr) ; eprintln ! ("  Search stdout:\n{}" , stdout) ; eprintln ! ("  Search stderr:\n{}" , stderr) ; if let Some (output_file) = & details . output_file { let mut file = fs :: File :: create (output_file) . with_context (| | format ! ("Failed to create output file: {:?}" , output_file)) ? ; file . write_all (stdout . as_bytes ()) . with_context (| | format ! ("Failed to write stdout to file: {:?}" , output_file)) ? ; file . write_all (stderr . as_bytes ()) . with_context (| | format ! ("Failed to write stderr to file: {:?}" , output_file)) ? ; eprintln ! ("  Search output saved to {:?}" , output_file) ; } Ok (()) }